#!/usr/bin/env python3
"""Apply the documented continuation of the interrupted editorial review once."""
import hashlib
import json
from pathlib import Path

REV = Path(__file__).resolve().parent
LOG = REV / 'audit/resume-changes.json'
changes = []


def edit(chapter, old, new, reason, dependencies=None):
    path = REV / f'chapters/{chapter:02}.md'
    text = path.read_text()
    assert text.count(old) == 1, (chapter, old[:100], text.count(old))
    before = hashlib.sha256(path.read_bytes()).hexdigest()
    text = text.replace(old, new, 1)
    path.write_text(text)
    changes.append({'chapter': chapter, 'old': old, 'new': new, 'reason': reason,
                    'dependencies': dependencies or [chapter],
                    'status': 'applied_editorial', 'before_chapter_sha256': before,
                    'after_chapter_sha256': hashlib.sha256(path.read_bytes()).hexdigest()})


if __name__ == '__main__':
    assert not LOG.exists(), 'One-time patch already applied; preserve its history.'
    manifest = json.loads((REV / 'archive/resumed-before-final-review.json').read_text())
    for record in manifest['chapters']:
        assert hashlib.sha256((REV / record['file']).read_bytes()).hexdigest() == record['sha256']

